// Action function for rule: Grammar
fn onGrammar(c: *interpreter.Current, initializer: interpreter.Value, rules: interpreter.Value) !interpreter.Value {
    
    const pos = c.astPos();

    // create the grammar, assign its initializer
    const g = try c.allocator.create(ast.Grammar);
    g.* = ast.Grammar{
        .pos = pos,
        .init = null,
        .rules = std.ArrayList(*ast.Rule).init(c.allocator),
    };

    if (initializer) |init_val| {
        g.init = @as(*ast.CodeBlock, @ptrCast(init_val));
    }

    const rules_slice = @as([]const []const u8, @ptrCast(rules));
    for (rules_slice) |rule_val| {
        const rule_ptr = @as(*ast.Rule, @ptrCast(rule_val));
        try g.rules.append(c.allocator, rule_ptr);
    }

    return g;

}

// Action function for rule: Initializer
fn onInitializer(c: *interpreter.Current, code: interpreter.Value) !interpreter.Value {
    _ = c;
    
    return code;

}

// Action function for rule: Rule
fn onRule(c: *interpreter.Current, name: interpreter.Value, display: interpreter.Value, expr: interpreter.Value) !interpreter.Value {
    
    const pos = c.astPos();

    const rule = try c.allocator.create(ast.Rule);
    rule.* = ast.Rule{
        .pos = pos,
        .name = name.*,
        .display_name = undefined,
        .expression = undefined,
        .expr = undefined,
        .visited = false,
        .nullable = false,
        .left_recursive = false,
        .leader = false,
    };

    if (display) |display_val| {
        rule.display_name = @as(ast.StringLit, @ptrCast(display_val));
    } else {
        rule.display_name = ast.StringLit{
            .pos = pos,
            .value = "",
        };
    }

    const expr_ptr = try c.allocator.create(ast.Expression);
    expr_ptr.* = expr;
    rule.expr = expr_ptr;
    rule.expression = expr;

    return rule;

}

