// Parse entry function
// Note: This returns a static grammar template, not a dynamically parsed one
pub fn parse(allocator: std.mem.Allocator, filename: []const u8, source: []const u8) !*ast.Grammar {
    _ = filename;
    _ = source;
    // Get the static grammar structure
    return getGrammar(allocator);
}
